    aw_s->iirLowSampleRA = iirLowSampleRA;
    aw_s->iirLowSampleRB = iirLowSampleRB;
    aw_s->iirLowSampleRC = iirLowSampleRC;
    aw_s->iirLowSampleRD = iirLowSampleRD;
    aw_s->iirLowSampleRE = iirLowSampleRE;
    aw_s->iirHighSampleR = iirHighSampleR;
    aw_s->iirLowSampleR = iirLowSampleR;
    aw_s->tripletLA = tripletLA;
    aw_s->tripletLB = tripletLB;
    aw_s->tripletLC = tripletLC;
    aw_s->tripletFactorL = tripletFactorL;
    aw_s->tripletRA = tripletRA;
    aw_s->tripletRB = tripletRB;
    aw_s->tripletRC = tripletRC;
    aw_s->tripletFactorR = tripletFactorR;
