    aw_s->lowpassSampleLBB = lowpassSampleLBB;
    aw_s->lowpassSampleLCA = lowpassSampleLCA;
    aw_s->lowpassSampleLCB = lowpassSampleLCB;
    aw_s->lowpassSampleLDA = lowpassSampleLDA;
    aw_s->lowpassSampleLDB = lowpassSampleLDB;
    aw_s->lowpassSampleLE = lowpassSampleLE;
    aw_s->lowpassSampleLF = lowpassSampleLF;
    aw_s->lowpassSampleLG = lowpassSampleLG;
    aw_s->lowpassSampleRAA = lowpassSampleRAA;
    aw_s->lowpassSampleRAB = lowpassSampleRAB;
    aw_s->lowpassSampleRBA = lowpassSampleRBA;
    aw_s->lowpassSampleRBB = lowpassSampleRBB;
    aw_s->lowpassSampleRCA = lowpassSampleRCA;
    aw_s->lowpassSampleRCB = lowpassSampleRCB;
    aw_s->lowpassSampleRDA = lowpassSampleRDA;
    aw_s->lowpassSampleRDB = lowpassSampleRDB;
    aw_s->lowpassSampleRE = lowpassSampleRE;
    aw_s->lowpassSampleRF = lowpassSampleRF;
    aw_s->lowpassSampleRG = lowpassSampleRG;
    aw_s->highpassSampleLAA = highpassSampleLAA;
    aw_s->highpassSampleLAB = highpassSampleLAB;
    aw_s->highpassSampleLBA = highpassSampleLBA;
    aw_s->highpassSampleLBB = highpassSampleLBB;
    aw_s->highpassSampleLCA = highpassSampleLCA;
    aw_s->highpassSampleLCB = highpassSampleLCB;
    aw_s->highpassSampleLDA = highpassSampleLDA;
    aw_s->highpassSampleLDB = highpassSampleLDB;
    aw_s->highpassSampleLE = highpassSampleLE;
    aw_s->highpassSampleLF = highpassSampleLF;
    aw_s->highpassSampleRAA = highpassSampleRAA;
    aw_s->highpassSampleRAB = highpassSampleRAB;
    aw_s->highpassSampleRBA = highpassSampleRBA;
    aw_s->highpassSampleRBB = highpassSampleRBB;
    aw_s->highpassSampleRCA = highpassSampleRCA;
    aw_s->highpassSampleRCB = highpassSampleRCB;
    aw_s->highpassSampleRDA = highpassSampleRDA;
    aw_s->highpassSampleRDB = highpassSampleRDB;
    aw_s->highpassSampleRE = highpassSampleRE;
    aw_s->highpassSampleRF = highpassSampleRF;
    aw_s->flip = flip;
    aw_s->flipthree = flipthree;
